import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    target = torch.tensor(float(int(ctx.index) % 4))
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(target)}
dataset = synth.Spec("wasserstein-1d-regression", generator=samples, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("regression", split="train", input_field="inputs", target_field="targets", preserve_shape=True)
class ScalarPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=1)
    def forward(self, inputs):
        return self.network(inputs).squeeze(-1)
trainer = Trainer(ScalarPredictor(), train, recipe="regression", recipe_config={"loss": "wasserstein-1d"}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
